    internal static int TZeros(emon.Port.Buf b, int n) {
        // The caller's part of the contract: `n` zero bytes to paint on.
        int i = 0;
        while (i < n) {
            emon.Port.BufPush(b, 0);
            i += 1;
        }
        return 0;
    }
    internal static int TDec(int emonT, emon.Port.Cells ws, byte[] d, int k, int cols, int rows, int flags, int want, int nbytes, int b0, int b1, int b2, int b3, string msg) {
        emon.Port.Buf @out = emon.Port.NewBuf();
        TZeros(@out, rows * ((cols + 7) / 8));
        int st = Ccitt.CcDecode(d, 0, emon.Port.BlobLen(d), k, cols, rows, flags, @out, ws);
        emon.Testport.AssertEq(st, want, msg);
        if (want == 0) {
            emon.Testport.AssertEq(emon.Port.BufLen(@out), nbytes, msg);
            if (b0 >= 0) {
                emon.Testport.AssertEq(emon.Port.BufAt(@out, 0), b0, msg);
            }
            if (b1 >= 0) {
                emon.Testport.AssertEq(emon.Port.BufAt(@out, 1), b1, msg);
            }
            if (b2 >= 0) {
                emon.Testport.AssertEq(emon.Port.BufAt(@out, 2), b2, msg);
            }
            if (b3 >= 0) {
                emon.Testport.AssertEq(emon.Port.BufAt(@out, 3), b3, msg);
            }
        }
        return 0;
    }
    [Xunit.Fact]
    public static void TestCcittOutTooSmall() {
        // `out` must already hold the rows: 16 x 2 pixels is four bytes, and three are not enough (status 3).
        emon.Port.Cells ws = emon.Port.NewCells();
        emon.Port.Buf @out = emon.Port.NewBuf();
        TZeros(@out, 3);
        emon.Testport.AssertEq(Ccitt.CcDecode(emon.Testport.HexBlob("f0"), 0, 1, -1, 16, 2, 0, @out, ws), 3, "a buffer short of the rows");
    }
